{"fw_ld4_quick_f_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I don't want to be alone",2,"You're not alone",1,"Promise?",2,"Promise, now close your eyes"}},
{"fw_ld4_quick_f_0009","any",2,"reg=civilian,family,worker,rescue",{1,"How long have you been walking?",2,"Since the second",1,"Of July?",2,"Of everything"}},
{"fw_ld4_quick_f_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You gonna finish those?",2,"What?",1,"The crackers",2,"They're my crackers",1,"Share the love",2,"Share the crackers, first"}},
{"fw_ld4_quick_f_0011","any",2,"reg=civilian,family,worker,rescue",{1,"I want to cry but I can't",2,"Try thinking of something sad",1,"Everything is sad",2,"Then try thinking of something happy, the contrast might do it"}},
{"fw_ld4_quick_f_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, wanna hear a secret?",2,"Always",1,"I was scared of you the first day",2,"I was scared of YOU",1,"Look at us now"}},
{"fw_ld4_quick_f_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Why do you hum?",2,"Because silence is loud",1,"Hum louder, then",2,"That defeats the purpose"}},
{"fw_ld4_quick_f_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Open your hand",2,"Why?",1,"Just open it",2,"A candy corn, where did you get a candy corn?",1,"Some things are best left mysterious"}},
{"fw_ld4_quick_f_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I feel sick",2,"Did you eat something?",1,"The mystery can",2,"There's a reason it was a mystery"}},
{"fw_ld4_quick_f_0016","any",2,"reg=civilian,family,worker,rescue",{1,"Who taught you to shoot?",2,"My uncle",1,"A good teacher?",2,"A terrible shot, but he told great stories while doing it"}},
{"fw_ld4_quick_f_0017","any",2,"reg=civilian,family,worker,rescue",{1,"I'm a terrible person",2,"No",1,"I left a man behind",2,"Then you've regretted it every minute since - that counts for something"}},
{"fw_ld4_quick_f_0018","any",2,"reg=civilian,family,worker,rescue",{1,"What day do you think it is?",2,"Wednesday",1,"Why Wednesday?",2,"Because Wednesday's the day nothing ever happens, and I like that"}},
{"fw_ld4_quick_f_0019","any",2,"reg=civilian,family,worker,rescue",{1,"Did you hear me yell last night?",2,"No",1,"I had a nightmare",2,"Mine are loud too, welcome to the club"}},
{"fw_ld4_quick_f_0020","any",2,"reg=civilian,family,worker,rescue|world=building",{1,"Move over",2,"There's no room",1,"Make room",2,"I'm a wall, not a magician"}},
{"fw_ld4_quick_f_0021","any",2,"reg=civilian,family,worker,rescue",{1,"How many are we?",2,"Eleven",1,"Twelve with the dog",2,"The dog counts for two, he eats like three"}},
{"fw_ld4_quick_f_0022","any",2,"reg=civilian,family,worker,rescue",{1,"I miss my bed",2,"I miss my pillow",1,"I miss clean sheets",2,"Stop it, we've been through this"}},
{"fw_ld4_quick_f_0023","any",2,"reg=civilian,family,worker,rescue|world=summer",{1,"Think we'll live to see Christmas?",2,"Don't say that",1,"Why not?",2,"Because it's still summer, and you'll jinx the fall"}},
{"fw_ld4_quick_f_0024","any",2,"reg=civilian,family,worker,rescue",{1,"What's your name again?",2,"Frank",1,"I thought it was Fred",2,"It's been Frank for 52 years"}},
{"fw_ld4_quick_f_0025","any",2,"reg=civilian,family,worker,rescue",{1,"Think anyone's looking for us?",2,"Somebody",1,"Who?",2,"Somebody who loves us, I choose to believe it"}},
{"fw_ld4_quick_f_0026","any",2,"reg=civilian,family,worker,rescue",{1,"I'm tired of being brave",2,"Then be tired",1,"Won't that get me killed?",2,"Not if I'm brave for you, take turns"}},
{"fw_ld4_quick_f_0027","any",2,"reg=civilian,family,worker,rescue",{1,"Don't go yet",2,"I have to",1,"Five more minutes",2,"Five more minutes, then I'm gone, and I'm sorry"}},
{"fw_ld4_quick_f_0028","any",2,"reg=civilian,family,worker,rescue",{1,"Sing something sad",2,"Why?",1,"I want to cry",2,"Okay, 'Taps', but you hum the trumpet part"}},
{"fw_ld4_quick_f_0029","any",2,"reg=civilian,family,worker,rescue",{1,"This place gives me the creeps",2,"Everywhere gives you the creeps",1,"This one more",2,"Then let's go, I trust your creeps"}},
{"fw_ld4_quick_f_0030","any",2,"reg=civilian,family,worker,rescue",{1,"Who wants the last biscuit?",2,"Give it to the kid",1,"Agreed",2,"Agreed"}},
{"fw_ld4_quick_f_0031","any",2,"reg=civilian,family,worker,rescue",{1,"What do you want to be when this is over?",2,"Alive",1,"That's a start",2,"And bored, wonderfully bored"}},
{"fw_ld4_quick_f_0032","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"What if I'm the one who turns?",2,"You won't",1,"But what if?",2,"Then I'll hold your hand until the end, and I'll be quick"}},
{"fw_ld4_quick_f_0033","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I wish someone would hug me",2,"Come here",1,"Seriously?",2,"Seriously, my arms are free"}},
{"fw_ld4_quick_f_0034","any",2,"reg=law,swat",{1,"Remember the ten-codes?",2,"Ten-four, ten-twenty",1,"What's ten-seven?",2,"Out of service, and that's me, most days"}},
{"fw_ld4_quick_f_0035","any",2,"reg=law,swat",{1,"I'm too tired to be scared",2,"That's a dangerous place",1,"Where?",2,"Anyplace you'd be fine not coming back from"}},
{"fw_ld4_quick_f_0036","any",2,"reg=military,elite",{1,"Hooah",2,"Hooah what?",1,"Just hooah",2,"Hooah to you, too"}},
{"fw_ld4_quick_f_0037","any",2,"reg=military,elite",{1,"Think they'll court-martial us?",2,"For what?",1,"Surviving",2,"Only if we survive long enough to be tried"}},
{"fw_ld4_quick_f_0038","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You scared of dying?",2,"Nope",1,"Liar",2,"Fine, a little, mostly of dying boring"}},
{"fw_ld4_quick_f_0039","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You ever pray?",2,"Never",1,"Not even now?",2,"Especially not now, I'd be a hypocrite"}},
{"fw_ld4_quick_f_0040","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You gonna share?",2,"With you? Never",1,"Come on",2,"Fine, a sip, a tiny one"}},
{"fw_ld4_quick_f_0041","any",2,"reg=family",{1,"Mama, is Daddy coming back?",2,"I don't know, baby",1,"Will he find us?",2,"If anyone can, he can"}},
{"fw_ld4_quick_f_0042","any",2,"reg=family",{1,"Tell me when it's morning",2,"It's morning",1,"Is it light?",2,"A little",1,"Then it's morning, thank you"}},
{"fw_ld4_quick_f_0043","any",2,"reg=family",{1,"Grandma, why are your hands shaking?",2,"They're just old",1,"Do they hurt?",2,"Only when I don't hold something dear"}},
{"fw_ld4_quick_g_0001","any",2,"reg=civilian,family,worker,rescue",{1,"I can't believe we found a working lighter",2,"It's a miracle",1,"It's a Bic",2,"It's a Bic miracle"}},
{"fw_ld4_quick_g_0002","any",2,"reg=civilian,family,worker,rescue",{1,"You're humming that song again",2,"Which one?",1,"The one with no words, only 'da da da'",2,"Yep, da da da, that's all of it"}},
{"fw_ld4_quick_g_0003","any",2,"reg=civilian,family,worker,rescue",{1,"How do you do it?",2,"Do what?",1,"Keep so calm",2,"I'm screaming on the inside, I just have a really good poker face"}},
{"fw_ld4_quick_g_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Is that your stomach or the dog's?",2,"Dog",1,"Liar",2,"Fine, it's mine, I'm possessed by hunger"}},
{"fw_ld4_quick_g_0005","any",2,"reg=civilian,family,worker,rescue",{1,"What are you thinking about?",2,"Pie",1,"What kind?",2,"Cherry, with a lattice top",1,"Now I'm thinking about pie"}},
{"fw_ld4_quick_g_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Say 'cheese'",2,"Cheese",1,"Now you have a permanent record",2,"Of what?",1,"Of someone who said cheese in the apocalypse"}},
{"fw_ld4_quick_g_0007","any",2,"reg=civilian,family,worker,rescue",{1,"You have a nice voice",2,"Thanks",1,"You should talk more",2,"I only talk when it matters",1,"This matters",2,"Okay, hello, how are you"}},
{"fw_ld4_quick_g_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Which way?",2,"Left",1,"You sure?",2,"No",1,"Great, left it is"}},
{"fw_ld4_quick_g_0009","any",2,"reg=civilian,family,worker,rescue",{1,"I'd like to say thank you",2,"For what?",1,"For being you",2,"That is the nicest thing ever, I'm going to cry"}},
{"fw_ld4_quick_g_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You wanna talk about it?",2,"Not really",1,"I'm here if you do",2,"I know, that's the best part"}},
{"fw_ld4_quick_g_0011","any",2,"reg=civilian,family,worker,rescue",{1,"If you had one wish",2,"Hot dog",1,"A hot dog? That's your wish?",2,"With mustard... and a big soda"}},
{"fw_ld4_quick_g_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Be quiet, I'm trying to think",2,"About what?",1,"About how to be quiet",2,"Sure sounds like you're just sitting there"}},
{"fw_ld4_quick_g_0013","any",2,"reg=civilian,family,worker,rescue",{1,"I got a feeling",2,"Good or bad?",1,"Bad",2,"Oh, so it's Tuesday"}},
{"fw_ld4_quick_g_0014","any",2,"reg=civilian,family,worker,rescue",{1,"You look tired",2,"You look worse",1,"Thanks",2,"Anytime"}},
{"fw_ld4_quick_g_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Show me your teeth",2,"Why?",1,"To check",2,"For what?",1,"For anything",2,"...there's a piece of corn in there, that's it"}},
{"fw_ld4_quick_g_0016","any",2,"reg=civilian,family,worker,rescue",{1,"I don't know what to do",2,"Neither do I",1,"Then why are we both standing here?",2,"Because it's what you do when you don't know what to do"}},
{"fw_ld4_quick_g_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Pass the water",2,"It's the last bottle",1,"I know",2,"Sip, then, don't gulp"}},
{"fw_ld4_quick_g_0018","any",2,"reg=civilian,family,worker,rescue",{1,"What've you got your nose in?",2,"A label on a can",1,"Interesting?",2,"'Contains peaches', thrilling"}},
{"fw_ld4_quick_g_0019","any",2,"reg=civilian,family,worker,rescue",{1,"You fall asleep standing up",2,"It's a talent",1,"It's a danger",2,"It's both"}},
{"fw_ld4_quick_g_0020","any",2,"reg=civilian,family,worker,rescue",{1,"I'm too old for this",2,"Define old",1,"Forty-three",2,"You're a child, I'm sixty-one"}},
{"fw_ld4_quick_g_0021","any",2,"reg=civilian,family,worker,rescue",{1,"How many ways can you cook a potato?",2,"Boiled, baked, fried",1,"That's it?",2,"That's all we have, besides raw"}},
{"fw_ld4_quick_g_0022","any",2,"reg=civilian,family,worker,rescue",{1,"Don't die",2,"I'll try",1,"That's not a promise",2,"It's the best I can do"}},
{"fw_ld4_quick_g_0023","any",2,"reg=civilian,family,worker,rescue",{1,"You still have your wedding ring",2,"Of course",1,"I thought you'd sell it",2,"Who'd buy it?"}},
{"fw_ld4_quick_g_0024","any",2,"reg=civilian,family,worker,rescue",{1,"I found a clock",2,"Does it work?",1,"It's stuck at 3:14",2,"That's the best time to be stuck at"}},
{"fw_ld4_quick_g_0025","any",2,"reg=civilian,family,worker,rescue",{1,"What's the point of having a watch?",2,"Hope",1,"Hope?",2,"That one day it will be important what time it is"}},
{"fw_ld4_quick_g_0026","any",2,"reg=civilian,family,worker,rescue",{1,"Shhh, don't wake him",2,"He's snoring like a bear",1,"Let him, he earned it",2,"Yeah, that tracks"}},
{"fw_ld4_quick_g_0027","any",2,"reg=civilian,family,worker,rescue",{1,"Guess how many steps I took today",2,"A million",1,"Twenty thousand, give or take",2,"That's practically a million"}},
{"fw_ld4_quick_g_0028","any",2,"reg=civilian,family,worker,rescue",{1,"Do you ever dance?",2,"Never",1,"When this is over, we'll dance",2,"Promise?",1,"Promise"}},
{"fw_ld4_quick_g_0029","any",2,"reg=civilian,family,worker,rescue",{1,"Wait, what's that over there?",2,"I don't see anything",1,"Never mind, it's just a shadow",2,"Don't scare me like that"}},
{"fw_ld4_quick_g_0030","any",2,"reg=civilian,family,worker,rescue",{1,"You're my best friend",2,"I'm your only friend",1,"That's why you're my best friend",2,"I will take it"}},
{"fw_ld4_quick_g_0031","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I can't believe I'm still alive",2,"Me neither",1,"Why are we?",2,"Luck, and stubbornness, mostly stubbornness"}},
{"fw_ld4_quick_g_0032","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you think my parents are okay?",2,"I do",1,"Why?",2,"Because they raised you, and you're tough"}},
{"fw_ld4_quick_g_0033","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"How are you holding up?",2,"By a string",1,"Which string?",2,"The one that says 'don't be dramatic'"}},
{"fw_ld4_quick_g_0034","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"We should make a list",2,"Of what?",1,"Of things we'll do when it's over",2,"Number one, a bath, number two, a longer bath"}},
{"fw_ld4_quick_g_0035","any",2,"reg=law,swat|hour=4,9",{1,"Back to work",2,"Already?",1,"Always",2,"I've been working since before dawn",1,"And you'll work after dusk"}},
{"fw_ld4_quick_g_0036","any",2,"reg=law,swat",{1,"My feet are killing me",2,"Take your boots off",1,"Then I'll never get them on",2,"Then keep them on and suffer"}},
{"fw_ld4_quick_g_0037","any",2,"reg=military,elite",{1,"Pick up your feet",2,"I'm trying, Sergeant",1,"Try harder",2,"Yes, Sergeant, my feet are begging for mercy"}},
{"fw_ld4_quick_g_0038","any",2,"reg=military,elite",{1,"What's the word?",2,"Hold",1,"Hold what?",2,"Hold everything"}},
{"fw_ld4_quick_g_0039","any",2,"reg=military,elite",{1,"You eat yet?",2,"Not yet",1,"Eat",2,"Yes, Sergeant"}},
{"fw_ld4_quick_g_0040","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You're staring",2,"I'm thinking",1,"About what?",2,"About what I'm gonna steal next",1,"Take my hat",2,"Done"}},
{"fw_ld4_quick_g_0041","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Never trust a smiling man",2,"Why?",1,"He wants something",2,"I'm smiling",1,"And I want your sandwich"}},
{"fw_ld4_quick_g_0042","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, boss",2,"What?",1,"Can I go home?",2,"Where's home?",1,"...good question"}},
{"fw_ld4_quick_g_0043","any",2,"reg=family",{1,"Time for prayers",2,"Do I really have to?",1,"Yes",2,"But I'm hungry",1,"Pray hungry, God's listening"}},
{"fw_ld4_quick_g_0044","any",2,"reg=family",{1,"Where's my doll?",2,"Here",1,"She's dirty",2,"She's well-loved, there's a difference"}},
{"fw_ld4_quick_g_0045","any",2,"reg=family",{1,"Tell me about Grandpa",2,"He had a big laugh",1,"Louder than mine?",2,"Louder than a freight train, and just as welcome"}},
{"fw_ld4_quick_h_0001","any",2,"reg=civilian,family,worker,rescue",{1,"I had the weirdest dream",2,"Tell me",1,"I was back at work, and the boss was a goat",2,"What did the goat say?",1,"'Your timesheet is late', I woke up crying"}},
{"fw_ld4_quick_h_0002","any",2,"reg=civilian,family,worker,rescue",{1,"How long have we been walking?",2,"Since breakfast",1,"We didn't have breakfast",2,"Since the time breakfast was supposed to be"}},
{"fw_ld4_quick_h_0003","any",2,"reg=civilian,family,worker,rescue",{1,"You can lean on me",2,"I'm too heavy",1,"You're skin and bones",2,"I'm heavy skin and bones"}},
{"fw_ld4_quick_h_0004","any",2,"reg=civilian,family,worker,rescue",{1,"I don't like this quiet",2,"Make some noise",1,"Like what?",2,"Whisper something very loudly"}},
{"fw_ld4_quick_h_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Do you want half my blanket?",2,"You'll be cold",1,"I'll share the cold with you",2,"Huh... nobody's been that kind in a while"}},
{"fw_ld4_quick_h_0006","any",2,"reg=civilian,family,worker,rescue",{1,"I have a confession",2,"Go on",1,"I ate the last cookie",2,"There was a cookie?!",1,"There WAS, and now there isn't, and I'm sorry"}},
{"fw_ld4_quick_h_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Wanna talk about it?",2,"No",1,"Do you want me to sit here quietly?",2,"Yes",1,"Okay, I'm sitting, I'm quiet, I'm here"}},
{"fw_ld4_quick_h_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I'm so tired of being the strong one",2,"Let me be strong for a bit",1,"You?",2,"I can be strong for ten minutes, I've been practicing"}},
{"fw_ld4_quick_h_0009","any",2,"reg=civilian,family,worker,rescue",{1,"That's the worst hat I've ever seen",2,"It was my grandfather's",1,"It looks like a dead cat",2,"It looks like a dead cat that's been loved"}},
{"fw_ld4_quick_h_0010","any",2,"reg=civilian,family,worker,rescue|hour=4,9",{1,"If I'm not back by dawn",2,"Don't say it",1,"If I'm not back by dawn, you go without me",2,"I won't",1,"You will, promise me",2,"Fine, I promise, but you'd better be back"}},
{"fw_ld4_quick_h_0011","any",2,"reg=civilian,family,worker,rescue",{1,"What's the bravest thing you've done?",2,"Come out of my house",1,"That's it?",2,"That was a Thursday, and I'd been in there six days, it counts"}},
{"fw_ld4_quick_h_0012","any",2,"reg=civilian,family,worker,rescue",{1,"I want to go home",2,"I know",1,"Do you think it's still there?",2,"I think something's there, home's what you take with you"}},
{"fw_ld4_quick_h_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Quick, hold this",2,"What is it?",1,"A hot potato",2,"It's a rock",1,"A hot rock, then, don't drop it"}},
{"fw_ld4_quick_h_0014","any",2,"reg=civilian,family,worker,rescue",{1,"How do you stay so cheerful?",2,"I'm not cheerful, I'm faking",1,"You're good at it",2,"Thank you, I've had a lot of practice"}},
{"fw_ld4_quick_h_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Sorry about the smell",2,"What smell?",1,"Mine",2,"Oh, that smell, I stopped noticing three days ago"}},
{"fw_ld4_quick_h_0016","any",2,"reg=civilian,family,worker,rescue",{1,"Will it get better?",2,"It has to",1,"Why?",2,"Because it can't get much worse, mathematically"}},
{"fw_ld4_quick_h_0017","any",2,"reg=civilian,family,worker,rescue",{1,"I keep hearing this song",2,"Where?",1,"In my head",2,"Go on, sing it to me",1,"I only get the one line. Then it starts over"}},
{"fw_ld4_quick_h_0018","any",2,"reg=civilian,family,worker,rescue",{1,"Don't go in there",2,"Why not?",1,"It feels wrong",2,"Everything feels wrong",1,"Wronger"}},
{"fw_ld4_quick_h_0019","any",2,"reg=civilian,family,worker,rescue",{1,"I need a minute",2,"Take two",1,"I need more",2,"Take ten, I'll cover for you"}},
{"fw_ld4_quick_h_0020","any",2,"reg=civilian,family,worker,rescue",{1,"I used to think I was brave",2,"And now?",1,"Now I know I'm just stubborn",2,"Stubborn works"}},
{"fw_ld4_quick_h_0021","any",2,"reg=civilian,family,worker,rescue",{1,"What are you thankful for?",2,"Hot soup",1,"Hot soup?",2,"When it happens, it feels like a miracle"}},
{"fw_ld4_quick_h_0022","any",2,"reg=civilian,family,worker,rescue",{1,"Stop apologizing",2,"Sorry",1,"See?",2,"Sorry, sorry, stop, okay, I'm stopping"}},
{"fw_ld4_quick_h_0023","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think she's still alive?",2,"I do",1,"How can you be sure?",2,"I'm not, but I've decided to be"}},
{"fw_ld4_quick_h_0024","any",2,"reg=civilian,family,worker,rescue",{1,"I'm gonna miss this place",2,"You hate this place",1,"I hate it, and I'm gonna miss it",2,"Welcome to being human"}},
{"fw_ld4_quick_h_0025","any",2,"reg=civilian,family,worker,rescue",{1,"Think they have snacks wherever we're going?",2,"Always",1,"What kind?",2,"The kind that come in tiny bags and cost too much"}},
{"fw_ld4_quick_h_0026","any",2,"reg=civilian,family,worker,rescue",{1,"Take a deep breath",2,"I'm doing it",1,"Another",2,"Another",1,"Feeling better?",2,"A little, a little"}},
{"fw_ld4_quick_h_0027","any",2,"reg=civilian,family,worker,rescue",{1,"Don't forget to wash your hands",2,"With what?",1,"With the last of the water",2,"I'm not wasting water on germs",1,"Then waste it on dignity"}},
{"fw_ld4_quick_h_0028","any",2,"reg=civilian,family,worker,rescue",{1,"I think this is the longest day of my life",2,"It's been eleven hours",1,"Feels like eleven years",2,"That's what makes it long"}},
{"fw_ld4_quick_h_0029","any",2,"reg=civilian,family,worker,rescue",{1,"Come on, smile",2,"I forgot how",1,"Pull the corners of your mouth up",2,"Like this?",1,"That's a grimace, but it's a start"}},
{"fw_ld4_quick_h_0030","any",2,"reg=civilian,family,worker,rescue",{1,"Where did you learn to do that?",2,"My grandfather",1,"What did he do?",2,"Everything, he was a man who could fix a boat with a spoon"}},
{"fw_ld4_quick_h_0031","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I'm sorry I'm so slow",2,"You're fine",1,"I'm holding everyone back",2,"You're holding us together, that's different"}},
{"fw_ld4_quick_h_0032","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you think I could be a hero?",2,"You already are",1,"I haven't done anything",2,"You're still here, still trying, that's heroic enough"}},
{"fw_ld4_quick_h_0033","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Did you ever think we'd get this far?",2,"Never",1,"Me neither",2,"I thought I'd die on day three"}},
{"fw_ld4_quick_h_0034","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"You're the glue",2,"I'm the duct tape",1,"Same thing",2,"Duct tape is cooler"}},
{"fw_ld4_quick_h_0035","any",2,"reg=law,swat",{1,"I never wrote that report",2,"What report?",1,"The one about the first night",2,"Write it now, in your head, tell me",1,"It was loud, and dark, and we were not ready"}},
{"fw_ld4_quick_h_0036","any",2,"reg=law,swat",{1,"How's the radio?",2,"Still dead",1,"Keep trying",2,"I will, until it works or I do"}},
{"fw_ld4_quick_h_0037","any",2,"reg=military,elite",{1,"Think we'll get a medal?",2,"For what?",1,"For surviving",2,"We'll get a blanket and a cold meal, if we're lucky"}},
{"fw_ld4_quick_h_0038","any",2,"reg=outlaw,raider,gang,club,crime,prison|hour=16,22",{1,"Boss says we move at dusk",2,"Where to?",1,"A farm, he says",2,"Does it have a name?",1,"It has a lot of chickens and one angry farmer"}},
{"fw_ld4_quick_h_0039","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Pour me one",2,"Last one",1,"Then make it count",2,"To the dead, and the almost dead"}},
{"fw_ld4_quick_h_0040","any",2,"reg=family",{1,"Mama, what's that sound?",2,"Crickets",1,"Are they singing?",2,"They're always singing, we just stopped listening"}},
{"fw_ld4_quick_h_0041","any",2,"reg=family",{1,"Can I have a hug?",2,"Always",1,"A big one?",2,"The biggest I've got"}},
{"fw_ld4_quick_i_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Whatcha thinking?",2,"How funny it is that a week ago I was worried about a parking ticket",1,"Ha",2,"I'd frame that parking ticket now"}},
{"fw_ld4_quick_i_0002","any",2,"reg=civilian,family,worker,rescue",{1,"We forgot Gerald's birthday",2,"Gerald is dead",1,"I know, I still feel bad",2,"Then buy him a cake in your head"}},
{"fw_ld4_quick_i_0003","any",2,"reg=civilian,family,worker,rescue",{1,"What's the weirdest thing you've eaten?",2,"A cricket",1,"You ate a cricket?",2,"On a dare, in high school, it tasted like a burnt almond",1,"Well, we're coming back around to that"}},
{"fw_ld4_quick_i_0004","any",2,"reg=civilian,family,worker,rescue",{1,"I bet you can't hold your breath for a minute",2,"I can",1,"Go",2,"Nope, forty seconds, nope, thirty, I'm done",1,"Pathetic, I love it"}},
{"fw_ld4_quick_i_0005","any",2,"reg=civilian,family,worker,rescue",{1,"You ever play hide and seek?",2,"As a kid",1,"Wanna play now?",2,"It's not as fun when the seeker is dead and hungry"}},
{"fw_ld4_quick_i_0006","any",2,"reg=civilian,family,worker,rescue|world=trees",{1,"Mom always said I'd end up like this",2,"Like what?",1,"Alone, in the woods, with a pocketknife",2,"She said that?",1,"She said it as a joke, but she knew me"}},
{"fw_ld4_quick_i_0007","any",2,"reg=civilian,family,worker,rescue|world=rain",{1,"My knees hurt when it's about to rain",2,"It's always about to rain",1,"See? I'm never wrong",2,"Because you hedge"}},
{"fw_ld4_quick_i_0008","any",2,"reg=civilian,family,worker,rescue|world=water",{1,"You ever think about swimming?",2,"In what?",1,"In a lake, in a pool, anywhere",2,"I'd float for a month, I would, with my eyes closed"}},
